    match levels.binary_search_by_key(&tick, |l| l.0) {
        Ok(i) => {
            if qty_lot > 0 {
                levels[i].1 = qty;
            } else {
                levels.remove(i);
            }
        }
        Err(i) => {
            if qty_lot > 0 {
                levels.insert(i, (tick, qty));
            }
        }
    }
}

